const MS_PER_DAY = 86400000;

function parseDate(value) {
  if (
    typeof value !== "string" ||
    value.length !== 10 ||
    !/^\d{4}-\d{2}-\d{2}$/.test(value)
  ) {
    throw new RangeError("Expected a calendar date in YYYY-MM-DD form.");
  }

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));

  // Unlike Date.UTC, this does not reinterpret years 0-99 as 1900-1999.
  const parsed = new Date(0);
  parsed.setUTCFullYear(year, month - 1, day);

  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() !== month - 1 ||
    parsed.getUTCDate() !== day
  ) {
    throw new RangeError("Invalid calendar date.");
  }

  return parsed.getTime() / MS_PER_DAY;
}

const MIN_DAY = parseDate("0000-01-01");
const MAX_DAY = parseDate("9999-12-31");

function weekday(day) {
  // Day zero is Thursday. Normalize the remainder for pre-1970 dates.
  return (((day + 4) % 7) + 7) % 7;
}

function isWeekday(day) {
  const value = weekday(day);
  return value >= 1 && value <= 5;
}

function buildObservedHolidays(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of calendar dates.");
  }

  const observed = new Set();
  const weekends = [];

  // Reserve every weekday holiday before placing any weekend holiday.
  for (const holiday of holidays) {
    const day = parseDate(holiday);
    if (isWeekday(day)) {
      observed.add(day);
    } else {
      weekends.push(day);
    }
  }

  weekends.sort((a, b) => a - b);

  let afterPrevious = -Infinity;
  for (const day of weekends) {
    const monday = day + (weekday(day) === 6 ? 2 : 1);

    // Sorted weekend candidates cannot have a free weekday before the
    // previous placement, so avoid scanning those occupied days again.
    let candidate = Math.max(monday, afterPrevious);
    while (!isWeekday(candidate) || observed.has(candidate)) {
      candidate += 1;
    }

    observed.add(candidate);
    afterPrevious = candidate + 1;
  }

  return Array.from(observed).sort((a, b) => a - b);
}

function lowerBound(values, target) {
  let low = 0;
  let high = values.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (values[middle] < target) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

// Count business days in the inclusive interval [first, last].
function countBusinessDays(first, last, observed) {
  if (first > last) {
    return 0;
  }

  const length = last - first + 1;
  let count = Math.floor(length / 7) * 5;

  // Whole weeks preserve the starting weekday.
  for (let offset = 0; offset < length % 7; offset += 1) {
    if (isWeekday(first + offset)) {
      count += 1;
    }
  }

  const holidayCount =
    lowerBound(observed, last + 1) - lowerBound(observed, first);

  return count - holidayCount;
}

export function isBusinessDay(date, holidays = []) {
  const day = parseDate(date);
  const observed = buildObservedHolidays(holidays);

  return isWeekday(day) && observed[lowerBound(observed, day)] !== day;
}

export function addBusinessDays(date, n, holidays = []) {
  const startDay = parseDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer.");
  }

  const observed = buildObservedHolidays(holidays);
  let first;
  let last;
  let target;

  if (n < 0) {
    first = MIN_DAY;
    last = startDay - 1;

    const available = countBusinessDays(first, last, observed);
    if (-n > available) {
      throw new RangeError("Result is outside the YYYY-MM-DD date range.");
    }

    // Convert a backward position into a forward rank in this interval.
    target = available + n + 1;
  } else {
    first = startDay + (n === 0 ? 0 : 1);
    last = MAX_DAY;
    target = n === 0 ? 1 : n;

    if (target > countBusinessDays(first, last, observed)) {
      throw new RangeError("Result is outside the YYYY-MM-DD date range.");
    }
  }

  // Find the first date on which the cumulative count reaches the target.
  const intervalStart = first;
  while (first < last) {
    const middle = first + Math.floor((last - first) / 2);

    if (countBusinessDays(intervalStart, middle, observed) >= target) {
      last = middle;
    } else {
      first = middle + 1;
    }
  }

  return new Date(first * MS_PER_DAY).toISOString().slice(0, 10);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDay = parseDate(start);
  const endDay = parseDate(end);
  const observed = buildObservedHolidays(holidays);

  if (startDay <= endDay) {
    return countBusinessDays(startDay + 1, endDay, observed);
  }

  const count = countBusinessDays(endDay + 1, startDay, observed);
  return count === 0 ? 0 : -count;
}
